    "description": "VVIP 한 국 인\n\n서울.인천.경기 출장샵 최고의 서비스를 보장하는\nVVIP 한국인출장 입니다.\n어디서나 고객님이 불러주시면\n최대한 빠르게 달려가겠습니다.\n부드러운 손길로 고객님께 힐링으로\n보답하겠습니다. ❤\n\n< 서울&경기&인천 >\n출장샵 : 원하는 장소에서 받을 수 있어요\n일부지역은 불가능한점 양해 부탁드려요",
    "detailContent": "VVIP 한 국 인\n\n서울.인천.경기 출장샵 최고의 서비스를 보장하는\nVVIP 한국인출장 입니다.\n어디서나 고객님이 불러주시면\n최대한 빠르게 달려가겠습니다.\n부드러운 손길로 고객님께 힐링으로\n보답하겠습니다. ❤\n\n< 서울&경기&인천 >\n출장샵 : 원하는 장소에서 받을 수 있어요\n일부지역은 불가능한점 양해 부탁드려요\n\n【 오시는 길 】\n서울 경기 인천\n출장샵 : 원하는 장소에서 받을 수 있어요\n일부지역은 불가능한점 양해 부탁드려요\n번거로운 외출 없이,\n가장 편안한 독립된 공간에서\n누리는 아늑한 명품 케어.\n엄선된 실력과 세련된 매너를 갖춘\n한국인 관리사 가 직접 찾아가 최상의 힐링을 선사합니다.\n일상의 피로를 녹이는 섬세한 손길,\n오직 당신만을 위해 준비된 럭셔리 홈테라피로\n격이 다른 휴식을 경험하십시오.\n후회 없는 선택, vip한국인 이 당신의 품격을 완성해 드립니다.\n★ 부재시 문자(예약시간/코스)부탁드립니다 ★ 100% 예약제 입실 후 선불 결제 ★ 예약 시간 10분 초과 예약자동취소\n\n【 영업시간 】\n24시간",
    "directions": "서울 경기 인천\n출장샵 : 원하는 장소에서 받을 수 있어요\n일부지역은 불가능한점 양해 부탁드려요\n번거로운 외출 없이,\n가장 편안한 독립된 공간에서\n누리는 아늑한 명품 케어.\n엄선된 실력과 세련된 매너를 갖춘\n한국인 관리사 가 직접 찾아가 최상의 힐링을 선사합니다.\n일상의 피로를 녹이는 섬세한 손길,\n오직 당신만을 위해 준비된 럭셔리 홈테라피로\n격이 다른 휴식을 경험하십시오.\n후회 없는 선택, vip한국인 이 당신의 품격을 완성해 드립니다.\n★ 부재시 문자(예약시간/코스)부탁드립니다 ★ 100% 예약제 입실 후 선불 결제 ★ 예약 시간 10분 초과 예약자동취소",
