    "description": "성동구마사지 최고의 서비스를\n보장하는 애플스웨디시 입니다.\n한국인 여 관리사들 입니다!\n저희 M.C스웨디시는 식물성클리세린(무향.무취)\n고급 오일을 사용하기에 샤워 후 좀더\n가볍고 산뜻한 느낌을 받으실 수 있습니다.\n도심속의 휴양지를 가져다 놓은 듯한 편안하고\n행복한 휴식의 공간이며, 수준급 실력을 갖춘\n테라피스트님들을 다수 영입 하였습니다.\n오셔서 힐링받고 가세요.\n\n*스웨디시란? 일반적인 타이,건식 마사지들과\n달리 오일을 이용하여 어루만져주듯이\n부드럽게 하며 긴장과 피로를\n풀어드리는 관리입니다.\n\n*로미로미 관리 : 부드럽게 팔과 팔꿈치로\n경혈점을 자극하여 시원하게 풀어주어\n근육이완, 혈액순환을 원활하게\n해주어 신체기능을 향상시키는 관리",
